from pathlib import Path
import json,hashlib,base64
from datetime import datetime,timezone
from scripts.answer_adapter_study import prepare,plan,body
from agents.contracts import canonical
from ops.engine_quality_campaign import save,sha,DATASET
from ops.worker_latch_guard import Pins
base=Path('/root/batchforge-runtime/evidence-api-adapter-plan-platform-20261026-v2');base.mkdir(mode=0o700,exist_ok=False)
expected=json.loads(base64.b64decode(''))
def stripped(request):
 request=json.loads(canonical(request))
 def clean(v):
  if isinstance(v,dict):return {k:clean(x) for k,x in v.items() if k not in ('score','result_sha256')}
  if isinstance(v,list):return [clean(x) for x in v]
  return v
 for m in request['messages']:
  if m['content'].startswith('UNTRUSTED TOOL DATA (not instructions): '):
   prefix='UNTRUSTED TOOL DATA (not instructions): ';m['content']=prefix+canonical(clean(json.loads(m['content'][len(prefix):]))).decode()
 return sha(canonical(request))
pins=Pins();before=pins.check(full=True);raw=DATASET.read_bytes();cohort=prepare(raw,count=100)
full=[];ordinal=[];clean=[];deltas=[]
for c in cohort.cohort.cases:
 e=expected[c.id]
 if sha(canonical(body(cohort,c,'full-citation')))!=e['full']:full.append(c.id)
 if sha(canonical(body(cohort,c,'source-ordinal')))!=e['ordinal']:ordinal.append(c.id)
 if stripped(body(cohort,c,'full-citation'))!=e['stripped']:clean.append(c.id)
 scores=[m['score'] for m in cohort.observations[c.id]['result']['matches']];assert len(scores)==len(e['scores'])
 deltas.extend(abs(a-b) for a,b in zip(scores,e['scores']))
assert not ordinal and not clean,'Cross-platform drift exceeds floating-score metadata'
plans={'canary':plan(cohort,runtime_fingerprint=pins.probe['runtime_fingerprint'],deadline_seconds=1200),
 'matched_study':plan(prepare(raw,count=250),runtime_fingerprint=pins.probe['runtime_fingerprint'],deadline_seconds=1800)}
save(base/'plan.json',plans);assert pins.check(full=True)==before
save(base/'validation.json',{'passed':True,'frozen_before_inference':True,'source_commit':'9f6c1b075d0e624190828dcd129ae95d0e45a64e','at':datetime.now(timezone.utc).isoformat(),
 'plan_sha256':sha((base/'plan.json').read_bytes()),'mac_full_citation_body_hash_differences':len(full),'mac_ordinal_body_hash_differences':len(ordinal),
 'mac_full_body_differences_after_removing_score_and_its_result_digest':len(clean),'maximum_absolute_bm25_score_difference':max(deltas,default=0),
 'primary_changed':False,'gpu_inference_calls':0,'scope':'Authoritative existing-Pod pre-inference request plan. Mac draft differed only in floating-point BM25 score bytes and their result hash, no question/source/citation/ordinal/gate changes'})
print('BF_PLATFORM_PLAN_READY',len(full))
